<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($ticket['ticket_number']) ?> | Helpdesk Carrousel</title><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/app.css"><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/layout-fixes.css"></head><body><div class="brand-strip"></div><main class="content" style="max-width:1050px;margin:auto"><div class="page-heading"><div><h1 class="page-title"><?= htmlspecialchars($ticket['ticket_number']) ?></h1><p class="page-subtitle"><?= htmlspecialchars($ticket['subject']) ?></p></div><div><a class="btn btn-outline-secondary" href="<?= APP_BASE_URL ?>/tickets">Mis tickets</a> <a class="btn btn-outline-secondary" href="<?= APP_BASE_URL ?>/dashboard">Dashboard</a></div></div><?php if(!empty($flash)): ?><div class="alert"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?><div class="grid grid-3"><section class="card stat"><span class="stat-label">Estado</span><b><?= htmlspecialchars(str_replace('_',' ',$ticket['status'])) ?></b></section><section class="card stat"><span class="stat-label">Prioridad</span><b><?= htmlspecialchars($ticket['priority']) ?></b></section><section class="card stat"><span class="stat-label">Asignado a</span><b><?= htmlspecialchars($ticket['assigned_name']??'Pendiente') ?></b></section></div><section class="card" style="margin-top:18px"><div class="card-body"><h2>Detalle</h2><p><strong>Solicitante:</strong> <?= htmlspecialchars($ticket['requester_name']) ?> · <?= htmlspecialchars($ticket['requester_email']) ?></p><p><strong>Parque:</strong> <?= htmlspecialchars($ticket['park_name']??'—') ?> · <strong>Área:</strong> <?= htmlspecialchars($ticket['area_name']??'—') ?> · <strong>Categoría:</strong> <?= htmlspecialchars($ticket['category_name']??'—') ?></p><p style="white-space:pre-wrap"><?= htmlspecialchars($ticket['description']) ?></p></div></section><section class="card" style="margin-top:18px"><div class="card-body"><h2>Historial</h2><?php foreach($events as $e): ?><div style="padding:10px 0;border-bottom:1px solid rgba(127,127,127,.2)"><strong><?= htmlspecialchars(str_replace('_',' ',$e['event_type'])) ?></strong><div class="small subtle"><?= htmlspecialchars($e['created_at']) ?><?= !empty($e['actor_name'])?' · '.htmlspecialchars($e['actor_name']):'' ?></div></div><?php endforeach; ?><?php if(!$events): ?><p class="subtle">Sin movimientos registrados.</p><?php endif; ?></div></section></main></body></html>